import{_ as t,o as s,c as o,ag as n}from"./chunks/framework.qXLDknWC.js";const d=JSON.parse('{"title":"Recursion Map Guide","description":"","frontmatter":{},"headers":[],"relativePath":"features/recursion-map-guide.md","filePath":"features/recursion-map-guide.md"}'),a={name:"features/recursion-map-guide.md"};function r(i,e,l,h,c,u){return s(),o("div",null,[...e[0]||(e[0]=[n('<h1 id="recursion-map-guide" tabindex="-1">Recursion Map Guide <a class="header-anchor" href="#recursion-map-guide" aria-label="Permalink to &quot;Recursion Map Guide&quot;">​</a></h1><p>A hands-on walkthrough of the recursion map: what the picture means, and how to use it to wire up (or tame) recursive lorebook entries. If you only want a quick reference, the <a href="/CharacterVault/docs/features/lorebook-editor#recursion-map">Lorebook Editor</a> page has a summary. This guide is the slow version.</p><p><img src="https://i.imgur.com/BnMeHEJ.png" alt="The recursion map web view: entries as boxes, arrows for unlock paths, inspector on the right"></p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><details class="details custom-block"><summary>What recursion actually is</summary><p>In SillyTavern, a lorebook entry activates when the chat mentions one of its keys. With <strong>recursive scanning</strong> on, activated entries get a second life: the text of an activated entry is scanned too. So if lorebook entry A turns on, and A&#39;s <strong>content</strong> happens to contain one of entry B&#39;s <strong>keys</strong>, B can turn on as well. B&#39;s content then gets scanned, which can wake up C, and so on.</p><p>That&#39;s a chain reaction. Done well, it makes a book feel alive: mentioning a tavern pulls in the tavern keeper, whose entry pulls in her quest. Done badly, one common word snowballs into a wall of context you never asked for.</p><p>The recursion map draws those chain reactions for the current book so you can see them before they surprise you.</p></details><details class="details custom-block"><summary>Reading the picture</summary><p>Open the map from book settings (<strong>Map</strong>) or an entry&#39;s <strong>Options</strong> panel (<strong>Map</strong>). You get a full-screen view where:</p><ul><li><strong>Each box is an entry.</strong></li><li><strong>Each arrow is a possible unlock.</strong> An arrow from A to B means A&#39;s content mentions one of B&#39;s keys. Hover the arrow (or the boxes) for the actual key.</li><li><strong>Clusters are families.</strong> Boxes that can reach each other sit together. Separate clusters are independent: nothing in one cluster can wake up anything in another.</li><li><strong>Dots on a box are flags.</strong> The legend at the bottom decodes them: blue for non-recursable, green for prevent further, grey for delay until recursion, yellow for disabled entries.</li></ul><p>Entries with no connections are hidden by default to keep the picture clean. <strong>Show standalone</strong> (top right) brings them in as dim boxes below the clusters. Useful for spotting entries you expected to be wired up but aren&#39;t.</p></details><details class="details custom-block"><summary>Getting around</summary><ul><li><strong>Drag</strong> the background to pan, <strong>scroll</strong> to zoom toward your cursor.</li><li><strong>Reset view</strong> fits the whole book back on screen.</li><li><strong>Hover</strong> an entry to spotlight just its connections and fade the rest. <strong>Click</strong> to pin those paths and open the inspector. Click the same entry again to clear the pin so the whole map is even.</li><li>The <strong>List</strong> button (top right) swaps the picture for a searchable table. Handy on very large books, which open in list mode automatically.</li></ul></details><details class="details custom-block"><summary>A first inspection</summary><p>Click any entry. A panel slides in on the right showing three things:</p><ol><li>The entry&#39;s keys (as chips) and flags.</li><li><strong>Unlocked by</strong>: entries whose content mentions this entry&#39;s keys. Each row shows the matched keys as chips, with the line <em>Mentions these keys in its content</em>.</li><li><strong>Unlocks</strong>: entries this entry can wake up. Each row shows that entry&#39;s matched keys as chips, with the line <em>These keys match in this content</em>.</li></ol><p>Click any entry in those two lists to inspect it instead. Walking those rows is the fastest way to follow a chain and check that each hop makes sense. Click the same box again, or the inspector <strong>X</strong>, to close the panel and drop the path highlight.</p><p>For quick fixes, edit the key chips or use the three flag buttons (<strong>Non-recursable</strong>, <strong>Prevent further recursion</strong>, <strong>Delay until recursion</strong>). Both write immediately.</p></details><details class="details custom-block"><summary>Editing keys on the map</summary><p>The chips are the entry&#39;s real primary keys. Changing them updates the lorebook entry and redraws the arrows. You do not have to close the map and go back to the Keys field, though that field stays in sync.</p><ul><li><strong>Inspector Keys</strong>: add, rename, or remove any of this entry&#39;s primary keys.</li><li><strong>Unlocked by chips</strong>: same list as inspector Keys (this entry owns them).</li><li><strong>Unlocks chips</strong>: the <em>other</em> entry&#39;s keys. Remove or rename one to break or retarget that hop without opening that entry first.</li></ul><p>Click a chip to rename it. Enter or blur saves; Escape cancels and leaves the map open. <strong>X</strong> removes it. Type next to the inspector chips and press Enter or comma to add a key.</p><p>These are the same keys SillyTavern uses to activate the entry from chat, not aliases for the picture. Secondary (selective) keys are not on the map.</p><p>The camera stays where you left it when arrows appear or vanish. <strong>Reset view</strong> recenters if a new cluster lands off-screen.</p></details><h2 id="flags" tabindex="-1">Flags <a class="header-anchor" href="#flags" aria-label="Permalink to &quot;Flags&quot;">​</a></h2><details class="details custom-block"><summary>The three flags, in plain terms</summary><table tabindex="0"><thead><tr><th style="text-align:left;">Flag</th><th style="text-align:left;">What it does in the chain</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Non-recursable</strong></td><td style="text-align:left;">This entry is a dead end for incoming chains. Other entries can name its keys all they want; it will not turn on through recursion. It can still activate normally from the chat.</td></tr><tr><td style="text-align:left;"><strong>Prevent further recursion</strong></td><td style="text-align:left;">When this entry activates, it unlocks nothing. A chain stops here even if its content mentions other keys.</td></tr><tr><td style="text-align:left;"><strong>Delay until recursion</strong></td><td style="text-align:left;">This entry ignores the first scan of the chat and only turns on via recursion. Good for &quot;deep lore&quot; that should only surface once a topic is already rolling.</td></tr></tbody></table><p>Two combinations cover most needs:</p><ul><li><strong>Standalone entry</strong>: non-recursable + prevent further. Fully out of the web; activates only from chat and chains nowhere.</li><li><strong>Seed entry</strong>: prevent further off, non-recursable on. Starts chains but nothing can recursively start it. Typical for hub entries like a location.</li></ul></details><details class="details custom-block"><summary>Changing many entries at once</summary><p>Sometimes a whole cluster needs taming. That&#39;s what selection is for:</p><ol><li><strong>Select entries.</strong> Ctrl (or Cmd) + click boxes on the web, or use the checkboxes in list view. Or use the shortcuts in the selection bar: <strong>All</strong>, <strong>Visible</strong> (current search results), or <strong>Linked</strong> (everything that has at least one path).</li><li><strong>Stage a change.</strong> In the bar that appears at the bottom, press On or Off next to a flag, or press <strong>Isolate: block both directions</strong>. Nothing happens yet. The bar shows exactly what is staged, which direction, and for how many entries.</li><li><strong>Commit or back out.</strong> Press <strong>Apply</strong> to write the change, or <strong>Discard</strong> to drop it. Staging something else, or changing the selection, clears the pending change. On selections above 25 entries, Apply asks for a second confirmation click.</li></ol><p>The map does not rearrange itself while you work. Flag changes don&#39;t add or remove paths (paths come from keys and content), so boxes stay put; only the flag dots update.</p></details><h2 id="common-repairs" tabindex="-1">Common repairs <a class="header-anchor" href="#common-repairs" aria-label="Permalink to &quot;Common repairs&quot;">​</a></h2><details class="details custom-block"><summary>A chain explodes into everything</summary><p>Inspect the entry where the explosion starts and look at its &quot;Unlocks&quot; list. Usually one broad key (a name, a place) is matching half the book. Tighten that target&#39;s keys on the hop chips, or set <strong>Prevent further recursion</strong> on the entry that fans out.</p></details><details class="details custom-block"><summary>Two entries keep re-triggering each other</summary><p>A mentions B&#39;s key, B mentions A&#39;s key. Flags can&#39;t break the loop by themselves. If the hop is a key you do not actually want, remove that chip on the Unlocks row. If the word should stay as a trigger but should not appear in the other entry&#39;s <strong>content</strong>, close the map and edit that prose.</p></details><details class="details custom-block"><summary>An entry never fires recursively</summary><p>Click it and check &quot;Unlocked by&quot;. Empty? Either nothing mentions its keys (rename the keys in the inspector chips, or mention them where you want), or <strong>Non-recursable</strong> is on, which the panel will say directly.</p></details><details class="details custom-block"><summary>Deep lore fires too early</summary><p>Set <strong>Delay until recursion</strong> so it stays quiet on the first chat scan and only joins once the topic is already active.</p></details><details class="details custom-block"><summary>What the map does not know</summary><p>The picture is built from primary keys in content. It deliberately ignores:</p><ul><li>secondary (selective) keys and their logic</li><li>activation probability</li><li>token budgets that might cut an entry mid-chain</li><li>how many scan steps SillyTavern actually runs</li></ul><p>So the map shows what <em>can</em> connect, not what <em>will</em> fire in a specific chat. It&#39;s for shaping the wiring, not predicting a single conversation. If <strong>Recursive scanning</strong> is off for the book, the map shows potential connections and reminds you that SillyTavern won&#39;t follow them until scanning is enabled.</p></details><h2 id="next-steps" tabindex="-1">Next steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a> - fields, entry editor, reference for the map</li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a> - managing standalone books</li><li><a href="/CharacterVault/docs/features/snapshots-history">Snapshots &amp; Rollback</a> - snapshot a book before big flag sweeps</li></ul>',20)])])}const g=t(a,[["render",r]]);export{d as __pageData,g as default};
